function UICultivateEquipBackpackNodeMB:RefreshFilterNode(dataList)
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.FilterNode.gameObject, FilterNodePath)
    if nodeEnv == nil then return end
    -- nodeEnv:SetFilterClass(Constants.UIFilterType.Equip)
    nodeEnv:SetCallback(dataList, Bind(self, self.OnClickFilterCellAction), Constants.UISortType.Equip)
    nodeEnv:SetExtraParams({career = base.GetCardCareerId(self)})
    nodeEnv:RestoreState(base.GetStoreKey(self), Bind(self, self.OnClickFilterCellAction))
end


---RefreshEquipBackpackByCompareState
---根据比较状态刷新背包
---@param compareState table
---@param newId number
---@param oldId number
---@param part number   -1 核心, > 0 装备
function UICultivateEquipBackpackNodeMB:RefreshEquipBackpackByCompareState(compareState, newId, oldId, part)
    --- 更新背包缓存数据
    if part == -1 then
        ---调用父类方法
        base.SetPlayerEquipCoreId(self, newId)
    else
        local equipIdList = base.GetEquipIdList(self)
        equipIdList[part] = newId
    end
    base.UpdateSuitDataPartList(self, compareState, newId, oldId, part)
    if compareState ~= CompareState.UninstallEquip then
        self:ClearSelectData()
    end
    self:ReloadScrollView()
end

---RefreshBackpackDataAndRefreshList
---@param newId number 背包中新增id
---@param oldId number 背包中要移除的id
---@param part number -1 核心, > 0 装备
function UICultivateEquipBackpackNodeMB:RefreshBackpackDataAndRefreshList(newId, oldId, part)

    if part == -1 then
        ---调用父类方法
        base.SetPlayerEquipCoreId(self, oldId)
    else
        local equipIdList = base.GetEquipIdList(self)
        equipIdList[part] = oldId
    end

    if self:GetFilterType() == FilTerType.SUIT then
        base.UpdateSuitDataPartList(self, newId, oldId, part)
    else
        self:UpdateBackpackDataPartList(newId, oldId, part)
    end

    self:ClearSelectData()

    --base.RefreshScrollView(self, base.GetBackpackDataList(self))
    self:RefreshFilterNode(base.GetBackpackDataList(self, self:GetFilterType() == FilTerType.SUIT))
end


function UICultivateEquipBackpackNodeMB:ReloadScrollView()
    --- 调用父类方法
    base.GetBackpackDataList(self, true)
end


---RefreshGoodsNode
---刷新道具节点
---@param mbEnv GoodNodeMB
---@param index number
function UICultivateEquipBackpackNodeMB:RefreshGoodsNode(mbEnv, index)
    --- 调用父类方法
    local backpackDataList = base.GetBackpackDataList(self)
    local backpackData     = backpackDataList[index]
    if not backpackData then return end
    local partType = backpackData.partType
    local dojo
    if partType == EQUIP_TYPE.Equip then
        dojo = equipComp:GetEquipById(backpackData.id)
    elseif partType == EQUIP_TYPE.Core then
        dojo = equipComp:GetEquipCoreById(backpackData.id)
    end
    --print(backpackData.id, backpackData.refId)
    base.RefreshGoodsNodeEnv(self, mbEnv, backpackData.id, backpackData.refId, nil,checkNumber(dojo.locked) > 0)

    local isSelect = self.selectIndex ~= nil and self.selectIndex == index
    mbEnv:SetCheckState(isSelect)

    mbEnv:SetEquipOrCoreSpecificState(dojo, base.GetCardCareerId(self))
end

function UICultivateEquipBackpackNodeMB:RefreshScrollViewAndUpdateSelectState()
    self.isDelayRefreshList = true
    --- 调用父类方法
    local oldBackpackDataList = base.GetBackpackDataList(self)
    local backpackDataList = base.GetBackpackDataList(self, true)
    --- 清空选中位置
    local selectId = 0
    if self.selectIndex ~= nil then
        if oldBackpackDataList[self.selectIndex] then
            selectId = checkNumber(oldBackpackDataList[self.selectIndex].id)
        end
        self.selectIndex = nil
    end
    if selectId > 0 then
        for i, v in ipairs(backpackDataList) do
            if checkNumber(v.id) == selectId then
                self.selectIndex = i
                break
            end
        end
    end
    --self:RefreshFilterNode(backpackDataList)
    base.RefreshScrollView(self, base.GetBackpackDataList(self))
end

---RefreshScrollViewByPart
---@param part number 0:all    -1: core    >0: equip part
function UICultivateEquipBackpackNodeMB:RefreshScrollViewByPart(part)
    base.RefreshScrollViewByPart(self, part)
    self:RefreshScrollViewAndUpdateSelectState()
end

