function UICultivateEquipBackpackNodeMB:OnClickCellAction(eventData)
    local selectedObject   = eventData.selectedObject
    local dataIndex        = selectedObject:GetComponent(IDType).id
    --- 调用父类方法
    local backpackDataList = base.GetBackpackDataList(self)
    local backpackData     = backpackDataList[dataIndex]
    local backpackDataId   = checkNumber(backpackData.id)

    --- update cell show state
    self:HideSelectIndex()

    --- 调用父类方法 根据下标刷新列表子节点显示状态
    base.RefreshCellShowStateByIndex(self, dataIndex, true)
    self.selectIndex = dataIndex

    if self.cellClickCallBack then
        self.cellClickCallBack(backpackDataId, backpackData.part, backpackData.partType, dataIndex)
    end
end

function UICultivateEquipBackpackNodeMB:HideSelectIndex()
    if self.selectIndex ~= nil then
        --- 调用父类方法 根据下标刷新列表子节点显示状态
        base.RefreshCellShowStateByIndex(self, self.selectIndex, false)
    end
end

function UICultivateEquipBackpackNodeMB:OnClickFilterCellAction(data)
    base.SetBackpackDataList(self, data)
    if not self.isDelayRefreshList then
        base.RefreshScrollView(self, data)
    end
    self.isDelayRefreshList = nil
end

